-- Question bank for topic-picker suggestions (189 reviewed questions).
-- Generated from question-bank/grade-*-question-bank.csv (human-reviewed).
-- served_suggestions tracks which questions each user has seen (no repeats).

create table if not exists question_bank (
  id         serial primary key,
  topic_id   text not null,
  topic      text not null,
  band       text not null,
  level      text not null,
  question   text not null,
  answer     text,
  source     text not null default 'reviewed_generated',
  created_at timestamptz default now()
);
create index if not exists idx_qbank_topic on question_bank (topic_id, band, level);

create table if not exists served_suggestions (
  user_id     uuid references auth.users(id) on delete cascade,
  question_id int references question_bank(id) on delete cascade,
  served_at   timestamptz default now(),
  primary key (user_id, question_id)
);
create index if not exists idx_served_user on served_suggestions (user_id, served_at);

